def bubble_sort(lst):

    for i in range(len(lst) - 1):
        flag = False

        # 对于每个元素，如果当前元素小于下一个元素，则交换它们
        for j in range(len(lst) - i - 1):
            if lst[j] < lst[j + 1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
                flag = True    

        # 如果在一次遍历中没有发生交换，那么列表已经排序，可以提前结束
        if not flag:
            break

    return lst

# 接受整数输入并将其转换为列表
data_list = list(map(int, input().split()))

sorted_list = bubble_sort(data_list)
